-- Rollback-only account fixtures. Never calls AI, booking or payment tools.
BEGIN;
CREATE FUNCTION pg_temp.chat_quota_assert(ok boolean,label text)RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'TEST FAILED: %',label;END IF;END$$;
DO $$
DECLARE u uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();root_id uuid:=gen_random_uuid();hid uuid:=gen_random_uuid();cid uuid;
 req uuid:=gen_random_uuid();blocked_req uuid:=gen_random_uuid();inp jsonb;trip_plan jsonb;claimed jsonb;outcome jsonb;proposal_before jsonb;updated_before timestamptz;denied boolean;i int;
BEGIN
 INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data)VALUES(u,'chat-quota-'||u||'@example.invalid',now(),'{}'),(outsider,'chat-quota-'||outsider||'@example.invalid',now(),'{}');
 inp:=jsonb_build_object('city','Shanghai','date',current_date+80,'guests',1,'prompt','Museum','days',1,'dayStart','09:00','dayEnd','20:00','transport','walk');
 trip_plan:='{"summary":"One visit","stops":[{"id":"amap_quotamuseum","dayIndex":1,"start":"09:00","end":"10:00","reason":"Museum"}]}';
 INSERT INTO journey_hub.trip_history(id,user_id,input,place_ids)VALUES(root_id,u,inp,ARRAY['amap_quotamuseum']);
 INSERT INTO journey_hub.trip_history(id,user_id,parent_id,input,place_ids,plan)VALUES(hid,u,root_id,inp,ARRAY['amap_quotamuseum'],trip_plan);
 outcome:=public.journeyhub_care_confirm(u,'history',hid);cid:=(outcome->>'id')::uuid;
 denied:=false;BEGIN PERFORM public.journeyhub_care_chat_start(u,cid,req,'',1);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='CARE_CHAT_INVALID';END;
 PERFORM pg_temp.chat_quota_assert(denied AND NOT EXISTS(SELECT FROM journey_hub.discovery_quota WHERE user_id=u),'invalid message is not charged');
 denied:=false;BEGIN PERFORM public.journeyhub_care_chat_start(outsider,cid,req,'Hello',1);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='CARE_CHAT_NOT_FOUND';END;
 PERFORM pg_temp.chat_quota_assert(denied AND NOT EXISTS(SELECT FROM journey_hub.discovery_quota WHERE user_id=outsider),'owner mismatch is not charged');
 outcome:=public.journeyhub_care_chat_start(u,cid,req,'Check my museum visit',1);
 PERFORM pg_temp.chat_quota_assert((SELECT uses=1 FROM journey_hub.discovery_quota WHERE user_id=u),'new chat consumes one shared use');
 PERFORM public.journeyhub_care_chat_start(u,cid,req,'Check my museum visit',1);
 PERFORM public.journeyhub_care_chat_read(u,cid);
 claimed:=public.journeyhub_care_chat_claim(u,cid,req);
 PERFORM public.journeyhub_care_chat_claim(u,cid,req);
 PERFORM pg_temp.chat_quota_assert((SELECT uses=1 FROM journey_hub.discovery_quota WHERE user_id=u),'replay read and claim do not consume quota');
 denied:=false;BEGIN PERFORM public.journeyhub_care_chat_start(u,cid,blocked_req,'Another question',1);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='CARE_CHAT_BUSY';END;
 PERFORM pg_temp.chat_quota_assert(denied AND (SELECT uses=1 FROM journey_hub.discovery_quota WHERE user_id=u),'busy request is not charged');
 PERFORM public.journeyhub_care_chat_fail(u,cid,req,(claimed->>'lease')::uuid,'Temporary failure.');
 FOR i IN 1..11 LOOP PERFORM public.journeyhub_discovery_quota(u);END LOOP;
 PERFORM pg_temp.chat_quota_assert((SELECT uses=12 FROM journey_hub.discovery_quota WHERE user_id=u),'chat shares the existing 12-use account quota');
 outcome:=public.journeyhub_care_chat_start(u,cid,req,'Check my museum visit',1);
 PERFORM pg_temp.chat_quota_assert(outcome#>>'{conversation,pending,status}'='pending' AND (SELECT uses=12 FROM journey_hub.discovery_quota WHERE user_id=u),'failed request retry stays free at exhausted quota');
 claimed:=public.journeyhub_care_chat_claim(u,cid,req);
 PERFORM public.journeyhub_care_chat_complete(u,cid,req,(claimed->>'lease')::uuid,'Your saved visit is ready for review.',NULL,'[]');
 proposal_before:=jsonb_build_object('id',gen_random_uuid(),'revision',1,'canApply',false,'summary','Keep this saved suggestion','expiresAt',now()+interval '20 minutes');
 PERFORM public.journeyhub_care_update(u,cid,1,NULL,proposal_before);
 SELECT updated_at INTO updated_before FROM journey_hub.trip_care WHERE id=cid;
 denied:=false;BEGIN PERFORM public.journeyhub_care_chat_start(u,cid,blocked_req,'A thirteenth request',1);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='rate limit reached';END;
 PERFORM pg_temp.chat_quota_assert(denied,'thirteenth new request is rejected');
 PERFORM pg_temp.chat_quota_assert(NOT EXISTS(SELECT FROM journey_hub.care_chat_requests WHERE user_id=u AND request_id=blocked_req),'exhaustion creates no request');
 PERFORM pg_temp.chat_quota_assert((SELECT proposal=proposal_before AND updated_at=updated_before FROM journey_hub.trip_care WHERE id=cid),'exhaustion does not clear proposal or update care');
 PERFORM pg_temp.chat_quota_assert((SELECT uses=12 FROM journey_hub.discovery_quota WHERE user_id=u),'rejected charge rolls back quota increment');
 outcome:=public.journeyhub_care_chat_start(u,cid,req,'Check my museum visit',1);
 PERFORM public.journeyhub_care_chat_read(u,cid);
 PERFORM pg_temp.chat_quota_assert(jsonb_array_length(outcome#>'{conversation,messages}')=2 AND (SELECT uses=12 FROM journey_hub.discovery_quota WHERE user_id=u),'completed replay and reads work at exhausted quota');
 PERFORM public.journeyhub_discovery_quota(outsider);
 PERFORM pg_temp.chat_quota_assert((SELECT uses=1 FROM journey_hub.discovery_quota WHERE user_id=outsider),'different account has its own quota');
 PERFORM pg_temp.chat_quota_assert(NOT has_function_privilege('authenticated','public.journeyhub_care_chat_start(uuid,uuid,uuid,text,integer)','EXECUTE'),'quota cannot be consumed with browser-spoofed owner');
 RAISE NOTICE 'PASS chat quota: new-only charge, replay/read/claim/retry free, shared limit, rejection atomicity and owner isolation';
END$$;
ROLLBACK;
